"""Story characters, past actions and manner."""
from english.u17.content import CORE, MEANINGS, picture
from english.study.author import word as w, question as q, choice as c, dialogue as d
from english.study.render import render_study as render

def data():
    words = [w('characters', k, v, 'The ' + k + ' is a main character.', image=k) for k, v in zip(CORE, MEANINGS)]
    words += [w('characters', k, v, e) for k, v, e in [('fox', 'con cáo', 'The fox is in the story.'), ('crow', 'con quạ', 'The crow is in the story.'), ('Snow White', 'Bạch Tuyết', 'Snow White cooked well.'), ('seven dwarfs', 'bảy chú lùn', 'The seven dwarfs are in the story.')]]
    words += [w('actions', k, v, e) for k, v, e in [('cooked well', 'nấu ăn giỏi', 'She cooked well.'), ('worked hard', 'làm việc chăm chỉ', 'He worked hard.'), ('ran fast', 'chạy nhanh', 'He ran fast.'), ('sang beautifully', 'hát hay', 'He sang beautifully.')]]
    words += [w('story', k, v, e) for k, v, e in [('main characters', 'nhân vật chính', 'Who are the main characters?'), ('fairy tale', 'truyện cổ tích', 'I am reading a fairy tale.'), ('storybook', 'sách truyện', 'Is this your storybook?'), ('won the race', 'đã thắng cuộc đua', 'The tortoise won the race.')]]
    dialogs = [d('characters', 'Nhân vật trong truyện', 'Who are the main characters in the story?', 'They are the ant and the grasshopper.', 'Đọc đúng truyện trên thẻ.'), d('characters', 'Một cặp nhân vật khác', 'Who are the main characters?', 'They are the tortoise and the hare.', 'Không nhầm hare với tortoise.'), d('actions', 'Hỏi cách chạy', 'How did he run?', 'He ran fast.', 'Did + run; câu kể ran.'), d('actions', 'Hỏi cách nấu', 'How did she cook?', 'She cooked well.', 'Did + cook; câu kể cooked.'), d('story', 'Hỏi Yes/No', 'Is this your storybook?', 'Yes, it is.', 'Câu hỏi Yes/No lên giọng như Lesson 3.'), d('story', 'Nói sở thích', 'Do you like the story?', 'Yes, I do. I like the ant.', 'Sở thích cần dựa lời người nói, không tự gán nhân vật tốt/xấu.')]
    exercises = [c('character-listen', 'characters', 'Which character is named?', 'grasshopper', 'Nghe grasshopper.', CORE, speech='The grasshopper is a main character.'), q('character-spell', 'characters', 'Complete: tor___. Write the whole word.', 'tortoise', 'Tortoise.'), q('character-plural', 'characters', 'Who are the main ___? Use nhân vật, plural.', 'characters', 'Main characters.'), q('character-full', 'characters', 'Rewrite in full: They’re the fox and the crow.', 'They are the fox and the crow.', 'They are.'), c('action-listen', 'actions', 'Which manner word is heard?', 'fast', 'He ran fast.', ['fast', 'well', 'hard', 'beautifully'], speech='He ran fast.'), q('action-base', 'actions', 'How did he ___? Use run.', 'run', 'Did + run, không ran.'), q('action-past', 'actions', 'He ___ beautifully. Use sing in the past.', 'sang', 'Sing → sang.'), q('action-sentence', 'actions', 'Card: she / cook / well, past. Write one sentence.', 'She cooked well.', 'Cook → cooked.'), c('story-listen', 'story', 'Who won this race?', 'tortoise', 'Nghe đúng kết thúc.', CORE, speech='The hare stopped to sleep. The tortoise won the race.'), q('story-tale', 'story', 'I am reading a fairy ___.', 'tale', 'Fairy tale.'), q('story-negative', 'story', 'Rewrite in full: He didn’t run.', 'He did not run.', 'Did not + run.'), q('story-question', 'story', 'Card: he / work. Write a How did question.', 'How did he work?', 'Did + work.')]
    return dict(unit=17, key='mia5:learn:en-u17-v1', intro='Nhận biết nhân vật, nghe kể ngắn, hỏi How did…? và luyện cách kể hành động đã qua.', groups=[dict(id='characters', name='Nhân vật truyện', tip='Who are the main characters in the story? They are… Snow White and the seven dwarfs; the ant and the grasshopper; the tortoise and the hare; the fox and the crow.'), dict(id='actions', name='Hành động và cách thực hiện', tip='How did he/she + nguyên mẫu? He/She + quá khứ + cách làm. Cook/cooked well; work/worked hard; run/ran fast; sing/sang beautifully.'), dict(id='story', name='Đọc, kể và nhịp câu', tip='Câu hỏi Yes/No thường lên giọng. Đọc chính đoạn/thẻ được giao vì truyện có nhiều dị bản. ABC là tên chữ cái, không phải phonics. Bài đọc và audio tự soạn.')], words=words, dialogues=dialogs, exercises=exercises)

def render_study():
    return render(data(), picture)
